var ngFileUpload = angular.module("ngFileUpload", []);

ngFileUpload.directive("ngfSelect", ["$parse", "$timeout", function($parse, $timeout) {
    return {
        restrict: "A",
        require: "ngModel",
        link: function(scope, element, attrs) {
            var fn = $parse(attrs.ngfSelect);
            element.on("change", function(event) {
                var files = event.target.files;
                if (files && files.length) {
                    fn(scope, { $files: files, $event: event });
                }
                if (files && files.length) {
                    event.target.value = "";
                }
            });
        }
    };
}]);

ngFileUpload.directive("ngfDrop", ["$parse", function($parse) {
    return {
        restrict: "A",
        require: "ngModel",
        link: function(scope, element, attrs) {
            var fn = $parse(attrs.ngfDrop);
            element.on("dragover", function(event) {
                event.preventDefault();
            });
            element.on("drop", function(event) {
                event.preventDefault();
                var files = event.dataTransfer.files;
                if (files && files.length) {
                    fn(scope, { $files: files, $event: event });
                }
            });
        }
    };
}]);

ngFileUpload.service("$upload", ["$http", "$q", function($http, $q) {
    return {
        upload: function(options) {
            var deferred = $q.defer();
            $http({
                url: options.url,
                method: options.method || "POST",
                headers: options.headers || {},
                transformRequest: function(data, headersGetter) {
                    var formData = new FormData();
                    angular.forEach(data, function(value, key) {
                        formData.append(key, value);
                    });
                    if (options.file) {
                        formData.append(options.file.name || "file", options.file);
                    }
                    return formData;
                },
                data: options.data || {},
                withCredentials: options.withCredentials || false
            }).success(function(data) {
                deferred.resolve(data);
            }).error(function(data) {
                deferred.reject(data);
            });
            return deferred.promise;
        }
    };
}]);